questionvariables.text:
/* Randomized Angles */
theta1: rand([25, 30, 35, 40]);
theta2: theta1 + rand([10, 15, 20]); /* Ensures the second angle is always larger */

/* Angles in radians for calculation */
t1: theta1*%pi/180;
t2: theta2*%pi/180;

/* Distance walked closer to the tower */
d: rand(5) + 8;

/* Native Float Calculations */
x_float: float(d * tan(t1) / (tan(t2) - tan(t1)));
h_float: float(x_float * tan(t2));

/* Display Variables */
h_disp: dispdp(h_float, 2);
x_disp: dispdp(x_float, 2);

/* Mistakes */
m1: float(d*tan(t1));
m2: float(d*tan(t2));
m3: float(d*(tan(t2)-tan(t1)));
